insert into public.gunung (nama, lokasi, ketinggian, jalur_populer, estimasi_waktu, harga_tiket, tingkat_kesulitan, gambar_url, deskripsi) values
('Gunung Prau', 'Dieng, Wonosobo, Jawa Tengah', 2565, 'Patak Banteng', '3 - 4 jam', 20000, 'Pemula', '/images/foto-prau.jpg', 'Gunung Prau dikenal sebagai surga bagi pendaki pemula karena jalurnya relatif pendek namun menyajikan panorama luar biasa. Puncaknya berupa padang sabana luas yang dijuluki Bukit Teletubbies, tempat terbaik menyaksikan golden sunrise dengan latar barisan Gunung Sindoro, Sumbing, Merapi, dan Merbabu. Suhu di area camp bisa turun hingga 5 derajat Celsius saat musim kemarau, sehingga perlengkapan hangat tetap wajib dibawa meskipun pendakian tergolong singkat.'),
('Gunung Sindoro', 'Temanggung, Jawa Tengah', 3153, 'Kledung', '6 - 8 jam', 25000, 'Menengah', '/images/foto-sindoro.jpg', 'Gunung Sindoro merupakan gunung berapi aktif bertipe strato yang berdiri berhadapan dengan Gunung Sumbing. Jalur Kledung menjadi pilihan paling populer karena akses transportasi mudah dan basecamp yang tertata. Pendaki akan melewati ladang tembakau, hutan pinus, kemudian padang edelweis di Watu Tatah sebelum mencapai kawah puncak. Trek berpasir pada pos akhir cukup menguras tenaga, sehingga manajemen air dan ritme langkah menjadi kunci keberhasilan pendakian.'),
('Gunung Sumbing', 'Temanggung - Wonosobo - Magelang, Jawa Tengah', 3371, 'Garung', '7 - 10 jam', 30000, 'Sulit', '/images/foto-sumbing.jpg', 'Gunung Sumbing adalah gunung tertinggi ketiga di Pulau Jawa dan berdiri tepat berhadapan dengan Gunung Sindoro, membentuk pemandangan gunung kembar yang menjadi ikon Jawa Tengah. Jalur Garung di Wonosobo merupakan yang paling ramai, sementara jalur Kaliangkrik di Magelang populer karena melewati Nepal van Java. Trek didominasi tanjakan panjang tanpa bonus, dengan padang edelweis dan sabana menjelang puncak. Stamina dan persediaan air menjadi penentu utama di gunung ini.'),
('Gunung Kerinci', 'Kayu Aro, Kerinci, Jambi', 3805, 'Kersik Tuo', '10 - 12 jam', 50000, 'Sulit', '/images/foto-kerinci.jpg', 'Gunung Kerinci adalah gunung berapi tertinggi di Indonesia sekaligus titik tertinggi Pulau Sumatra. Berada di kawasan Taman Nasional Kerinci Seblat, jalur pendakiannya menembus hutan hujan tropis lembap yang menjadi habitat harimau sumatra. Karakter trek berupa akar, lumpur dalam, dan batuan vulkanik lepas pada Tugu Yudha hingga puncak. Cuaca berubah sangat cepat dan kadar gas solfatara di kawah cukup tinggi, sehingga pendakian wajib didampingi informasi resmi dari balai taman nasional.'),
('Gunung Merbabu', 'Salatiga - Magelang, Jawa Tengah', 3145, 'Selo', '5 - 7 jam', 35000, 'Menengah', '/images/foto-merbabu.jpg', 'Gunung Merbabu terkenal dengan hamparan sabana bertingkat yang sering disebut sebagai salah satu yang terindah di Pulau Jawa. Jalur Selo menyajikan punggungan terbuka dengan pemandangan langsung ke Gunung Merapi yang berdiri gagah di seberang. Karena minim tegakan pohon, angin kencang dan paparan sinar matahari menjadi tantangan utama di sepanjang trek. Terdapat tiga puncak utama, yaitu Syarif, Kenteng Songo, dan Triangulasi, yang dapat dikunjungi dalam satu rangkaian pendakian.'),
('Gunung Bismo', 'Slukatan, Mojotengah, Wonosobo, Jawa Tengah', 2365, 'Silandak', '3 - 4 jam', 20000, 'Menengah', '/images/foto-bismo.jpg', 'Gunung Bismo berdiri di tepi kawasan Dataran Tinggi Dieng dan sering dijuluki balkon rahasia Dieng karena panoramanya yang terbuka ke segala arah. Dari puncaknya terlihat jelas barisan Sindoro, Sumbing, serta lautan awan yang menyelimuti lembah Wonosobo pada pagi hari. Jalur Silandak di Desa Slukatan menawarkan medan yang panjang dan penuh tanjakan, dengan beberapa bagian curam yang terbantu tali pengaman. Tersedia pula jalur alternatif via Ngandam dan Sikunang bagi yang menginginkan trek lebih ringan.'),
('Gunung Pakuwaja', 'Parikesit, Kejajar, Wonosobo, Jawa Tengah', 2421, 'Parikesit', '2 - 3 jam', 15000, 'Pemula', '/images/foto-pakuwaja.jpg', 'Gunung Pakuwaja merupakan salah satu puncak tertinggi di kawasan Dieng dengan hamparan sabana hijau yang menjadi daya tarik utamanya. Nama Pakuwaja berasal dari batu vertikal menjulang di area puncak yang menurut cerita masyarakat setempat dipercaya sebagai paku Pulau Jawa. Jalur dari Desa Parikesit tergolong singkat sehingga cocok untuk pendakian tektok maupun camping semalam. Dari puncak, Telaga Cebong, Bukit Sikunir, serta barisan gunung Dieng terlihat dalam satu bingkai.'),
('Gunung Ungaran', 'Semarang, Jawa Tengah', 2050, 'Mawar', '4 - 5 jam', 20000, 'Menengah', '/images/foto-ungaran.jpg', 'Gunung Ungaran adalah gunung terdekat dari Kota Semarang sehingga menjadi favorit pendaki akhir pekan dan lokasi latihan bagi pemula yang ingin naik kelas. Jalur Mawar melewati kebun teh Medini dan perkampungan Promasan yang masih dihuni warga pemetik teh. Pada cuaca cerah, puncaknya menyajikan pemandangan Rawa Pening, Gunung Merbabu, dan garis pantai utara Jawa sekaligus. Terdapat pula situs Candi Gedong Songo di lerengnya yang kerap dikunjungi sebelum atau sesudah pendakian.'),
('Gunung Andong', 'Girirejo, Ngablak, Magelang, Jawa Tengah', 1726, 'Sawit', '1 - 2 jam', 15000, 'Pemula', '/images/foto-andong.jpg', 'Gunung Andong adalah gunung bertipe perisai yang paling sering direkomendasikan untuk pendakian pertama karena jalurnya pendek, tertata, dan memiliki banyak warung di sepanjang pos. Jalur Sawit menjadi yang paling populer dari enam jalur resmi yang tersedia. Area puncaknya berupa punggungan memanjang bernama Geger Sapi yang menghubungkan beberapa titik puncak dengan pemandangan terbuka ke Merbabu, Telomoyo, dan Sumbing. Meski ringan, angin di punggungan cukup kencang sehingga pendirian tenda perlu diperhatikan.'),
('Gunung Telomoyo', 'Grabag, Magelang, Jawa Tengah', 1894, 'Jalur Motor Pos Pandean', '1 - 2 jam', 15000, 'Pemula', '/images/foto-telomoyo.jpg', 'Gunung Telomoyo unik karena puncaknya dapat dicapai dengan sepeda motor melalui jalan beraspal, menjadikannya favorit untuk wisata sunrise singkat dan latihan adaptasi ketinggian. Dari puncak terlihat panorama Rawa Pening, Gunung Andong, Merbabu, serta Sumbing dalam satu bingkai. Area puncak juga populer sebagai lokasi lepas landas paralayang. Meski ringan, kabut tebal pada dini hari sering menurunkan jarak pandang sehingga lampu penerangan tetap diperlukan.'),
('Gunung Rinjani', 'Lombok, Nusa Tenggara Barat', 3726, 'Sembalun', '2 - 3 hari', 150000, 'Sulit', '/images/foto-rinjani.jpg', 'Gunung Rinjani adalah gunung berapi tertinggi kedua di Indonesia dan berada di dalam kawasan Taman Nasional Gunung Rinjani. Daya tarik utamanya adalah Danau Segara Anak di dalam kaldera, lengkap dengan Gunung Barujari yang muncul di tengahnya serta sumber air panas alami di tepinya. Jalur Sembalun dimulai dari padang sabana luas yang terbuka tanpa naungan, lalu dilanjutkan Bukit Penyesalan berupa tujuh tanjakan beruntun menuju Plawangan. Pendakian umumnya memakan waktu tiga hari dua malam dan wajib didampingi porter atau pemandu terdaftar sesuai aturan taman nasional.'),
('Gunung Semeru', 'Lumajang - Malang, Jawa Timur', 3676, 'Ranu Pani', '2 - 3 hari', 120000, 'Sulit', '/images/foto-semeru.jpg', 'Gunung Semeru adalah puncak tertinggi di Pulau Jawa dengan titik tertingginya bernama Mahameru. Pendakian dimulai dari Ranu Pani, melewati Ranu Kumbolo yang terkenal dengan danau dan padang sabana Oro-Oro Ombo, lalu Kalimati sebagai camp terakhir. Kawah Jonggring Saloka di puncak mengeluarkan letusan asap secara berkala sehingga pendaki diwajibkan turun sebelum pukul sepuluh pagi saat arah angin berubah. Jalur pasir menuju Mahameru sangat melelahkan karena setiap langkah naik kerap diikuti melorot turun.'),
('Gunung Lawu', 'Karanganyar - Magetan, Jawa Tengah - Jawa Timur', 3265, 'Cemoro Sewu', '5 - 7 jam', 20000, 'Menengah', '/images/foto-lawu.jpg', 'Gunung Lawu berdiri di perbatasan Jawa Tengah dan Jawa Timur serta dikenal kuat dengan nuansa budaya dan spiritualnya. Jalur Cemoro Sewu berupa jalan batu tersusun rapi yang relatif aman walau menanjak terus-menerus. Di dekat puncak Hargo Dumilah terdapat Warung Mbok Yem, warung yang disebut sebagai salah satu warung tertinggi di Indonesia. Sumber air Sendang Drajat tersedia di jalur, namun pendaki tetap disarankan membawa persediaan sendiri karena debitnya tidak menentu.'),
('Gunung Slamet', 'Purbalingga - Banyumas, Jawa Tengah', 3428, 'Bambangan', '8 - 10 jam', 25000, 'Sulit', '/images/foto-slamet.jpg', 'Gunung Slamet adalah gunung tertinggi di Jawa Tengah dan tertinggi kedua di Pulau Jawa. Jalur Bambangan menjadi pintu masuk paling ramai dengan karakter trek menanjak panjang melewati hutan lebat sebelum tembus ke area terbuka. Bagian menjelang puncak berupa batuan vulkanik lepas dan pasir yang mudah longsor sehingga helm serta kewaspadaan terhadap batu jatuh sangat dianjurkan. Angin di area puncak sering sangat kencang dan kawahnya masih aktif mengeluarkan gas belerang.'),
('Gunung Papandayan', 'Cisurupan, Garut, Jawa Barat', 2665, 'Cisurupan', '3 - 4 jam', 30000, 'Pemula', '/images/foto-papandayan.jpg', 'Gunung Papandayan sangat cocok untuk pendaki pemula karena jalurnya landai, pendek, dan pemandangannya berganti-ganti sepanjang perjalanan. Pendaki melewati Kawah Mas yang mengepulkan asap belerang, Hutan Mati berisi batang pohon menghitam sisa letusan, lalu Tegal Alun berupa padang edelweis terluas di Jawa Barat. Area camp Pondok Saladah memiliki sumber air dan toilet sehingga nyaman untuk bermalam. Masker dan kacamata diperlukan saat melintasi area kawah karena asap belerang cukup menyengat.');
insert into public.alat (nama, kategori, berat_ideal, prioritas, konteks, gambar_url, fungsi, risiko_tanpa_alat) values
('Tas Carrier 60L', 'Tas & Penyimpanan', '2.1 kg', 'Wajib', 'semua', '/images/alat-tas-carrier.jpg', 'Tas carrier berkapasitas 60 liter berfungsi sebagai wadah utama seluruh logistik pendakian, mulai dari tenda, sleeping bag, pakaian ganti, air, hingga bahan makanan. Rangka internal dan sistem hip belt memindahkan sebagian besar beban dari punggung ke pinggul sehingga tubuh tetap seimbang saat melewati trek menanjak maupun turunan panjang.', 'Tanpa carrier yang layak, beban bertumpu penuh pada bahu dan tulang belakang. Risikonya adalah nyeri punggung bawah, cedera otot trapezius, kehilangan keseimbangan di jalur sempit, serta perlengkapan basah karena tidak terlindungi rain cover.'),
('Sleeping Bag Polar', 'Perlengkapan Tidur', '0.9 kg', 'Wajib', 'camp', '/images/alat-sleeping-bag.jpg', 'Sleeping bag berbahan polar menjaga suhu tubuh tetap stabil saat beristirahat di dalam tenda. Bahan ini memerangkap udara hangat hasil panas tubuh dan tetap terasa nyaman meskipun suhu lingkungan turun drastis pada dini hari di ketinggian di atas 2.000 meter.', 'Tidur tanpa sleeping bag di suhu dingin mempercepat kehilangan panas tubuh dan dapat memicu hipotermia, kondisi gawat darurat yang ditandai menggigil hebat, bicara melambat, dan penurunan kesadaran. Kualitas tidur yang buruk juga menurunkan stamina untuk perjalanan turun.'),
('Sepatu Tracking Waterproof', 'Alas Kaki', '1.2 kg', 'Wajib', 'semua', '/images/alat-sepatu-tracking.jpg', 'Sepatu tracking waterproof memberi cengkeraman kuat pada tanah basah, akar, dan batuan lepas melalui pola outsole yang agresif. Lapisan membran tahan air menjaga kaki tetap kering saat menembus kabut, embun pagi, atau hujan ringan, sementara bagian ankle melindungi pergelangan kaki dari gerakan memutar berlebih.', 'Menggunakan alas kaki tidak sesuai meningkatkan risiko tergelincir pada trek licin, lecet dan blister pada tumit, hingga keseleo atau cedera ligamen pergelangan kaki. Kaki yang terus basah juga rentan mengalami iritasi kulit dan infeksi jamur.'),
('Headlamp LED', 'Penerangan', '0.15 kg', 'Wajib', 'semua', '/images/alat-headlamp.jpg', 'Headlamp LED menjadi sumber cahaya utama untuk summit attack dini hari, memasak, maupun membongkar tenda saat gelap. Karena dipasang di kepala, kedua tangan tetap bebas untuk berpegangan pada akar maupun tali webbing di jalur terjal.', 'Tanpa penerangan, pendaki mudah kehilangan jejak jalur dan berisiko terjatuh ke jurang atau menginjak lubang tersembunyi. Pendakian pada gelap total juga memperlambat ritme kelompok dan mempersulit evakuasi jika terjadi keadaan darurat.'),
('Jaket Windproof', 'Pakaian Luar', '0.6 kg', 'Wajib', 'semua', '/images/alat-jaket-windproof.jpg', 'Jaket windproof menahan terpaan angin kencang di punggungan terbuka dan area sabana sehingga panas tubuh tidak cepat hilang. Material ripstop yang ringan dan cepat kering membuatnya ideal dipakai sebagai lapisan terluar dalam sistem berlapis bersama baselayer dan fleece.', 'Terpapar angin dingin terus-menerus memicu wind chill yang membuat suhu terasa jauh lebih rendah dari suhu sebenarnya. Dampaknya berupa kekakuan otot, penurunan koordinasi gerak, dan meningkatnya peluang hipotermia terutama bila pakaian dalam keadaan lembap.'),
('Matras Aluminium Foil', 'Perlengkapan Tidur', '0.35 kg', 'Penting', 'camp', '/images/alat-matras.jpg', 'Matras aluminium foil dipasang sebagai lapisan dasar di dalam tenda untuk memutus konduksi dingin dari permukaan tanah ke tubuh. Lapisan reflektifnya memantulkan kembali panas tubuh, sementara sisi busanya memberi bantalan terhadap kerikil dan permukaan tidak rata.', 'Tidur langsung di atas tanah membuat panas tubuh terserap permukaan sepanjang malam meskipun sudah memakai sleeping bag. Akibatnya tubuh tetap kedinginan, punggung terasa nyeri, dan pemulihan tenaga untuk hari berikutnya tidak maksimal.'),
('Trekking Pole Aluminium', 'Aksesori Pendukung', '0.5 kg', 'Opsional', 'semua', '/images/alat-trekking-pole.jpg', 'Trekking pole membantu mendistribusikan beban tubuh ke lengan sehingga tekanan pada lutut berkurang signifikan, terutama pada jalur turunan panjang. Tongkat ini juga berguna untuk menguji kestabilan pijakan, menyeberangi aliran air, dan menjaga ritme langkah tetap konsisten.', 'Tanpa trekking pole, sendi lutut menanggung beban kejut berulang saat menuruni jalur terjal yang dapat memicu nyeri tempurung lutut. Keseimbangan pada trek berbatu lepas juga lebih sulit dijaga sehingga risiko terpelincir meningkat.'),
('Kompor Portable dan Gas Kaleng', 'Masak & Logistik', '0.8 kg', 'Wajib', 'camp', '/images/alat-kompor-portable.jpg', 'Kompor portable berbahan bakar gas kaleng digunakan untuk memasak makanan hangat dan merebus air minum di area camp. Asupan makanan hangat berperan penting menjaga suhu inti tubuh serta memulihkan kalori yang terkuras selama perjalanan.', 'Tanpa alat memasak, pendaki hanya bergantung pada makanan dingin dan air mentah yang berisiko menyebabkan gangguan pencernaan. Ketidakmampuan menyajikan minuman hangat juga mempersempit pilihan penanganan awal saat ada anggota kelompok yang mulai kedinginan.'),
('Kotak P3K Pendakian', 'Keselamatan', '0.4 kg', 'Wajib', 'semua', '/images/alat-p3k.jpg', 'Kotak P3K berisi perban, plester, antiseptik, obat pereda nyeri, obat diare, serta obat pribadi milik anggota kelompok. Isinya dipakai untuk menangani luka lecet, terkilir, dan gangguan ringan di jalur agar masalah kecil tidak berkembang menjadi alasan evakuasi.', 'Tanpa P3K, luka terbuka berisiko terinfeksi karena jalur gunung penuh tanah dan air tidak steril. Keseleo yang tidak segera dibalut akan membengkak dan membuat korban tidak sanggup berjalan, sehingga satu cedera ringan bisa memaksa seluruh rombongan berhenti atau memanggil tim penyelamat.'),
('Tenda Dome Kapasitas 2 Orang', 'Perlindungan', '2.8 kg', 'Wajib', 'camp', '/images/alat-tenda.jpg', 'Tenda dome menjadi tempat berlindung utama saat bermalam di gunung. Lapisan flysheet menahan hujan dan embun, sementara rongga udara di dalamnya menahan angin sehingga suhu di dalam tenda terasa jauh lebih hangat daripada di luar.', 'Bermalam tanpa tenda berarti tubuh terpapar langsung angin, hujan, dan embun sepanjang malam. Pakaian yang basah di suhu rendah mempercepat hilangnya panas tubuh dan merupakan penyebab hipotermia yang paling sering terjadi pada pendaki di Indonesia.'),
('Jas Hujan dan Ponco', 'Pakaian Luar', '0.4 kg', 'Wajib', 'semua', '/images/alat-jas-hujan.svg', 'Jas hujan atau ponco melindungi tubuh dan isi tas saat hujan turun di tengah jalur. Model ponco yang lebar dapat sekaligus menutupi carrier sehingga perlengkapan tidur tetap kering tanpa perlu rain cover terpisah.', 'Cuaca gunung berubah sangat cepat dan hujan deras bisa datang tanpa tanda. Pakaian basah yang terkena angin membuat suhu tubuh turun drastis, dan sleeping bag yang ikut basah berarti tidak ada lagi tempat menghangatkan diri saat malam tiba.'),
('Nesting dan Alat Masak', 'Masak & Logistik', '0.6 kg', 'Wajib', 'camp', '/images/alat-nesting.jpg', 'Nesting adalah set panci, wajan, dan cangkir aluminium yang dapat disusun bertumpuk agar hemat ruang. Alat ini dipakai merebus air, memasak mi, dan menyeduh minuman hangat di area camp.', 'Tanpa nesting, kompor yang dibawa tidak ada gunanya. Pendaki terpaksa mengandalkan makanan dingin dan air mentah, padahal air sumber di gunung perlu dimasak terlebih dahulu untuk menghindari diare yang sangat melemahkan di tengah pendakian.'),
('Botol Air dan Hidrasi', 'Hidrasi', '1.5 kg', 'Wajib', 'semua', '/images/alat-botol-air.jpg', 'Botol air atau hydration pack menyimpan persediaan minum selama pendakian. Patokan umumnya dua liter per orang per hari, ditambah cadangan bila jalur yang dilalui tidak memiliki sumber air.', 'Dehidrasi di ketinggian datang lebih cepat daripada di dataran rendah karena udara kering dan napas yang memburu. Gejalanya berupa pusing, kram otot, dan penurunan konsentrasi, yang semuanya memperbesar peluang tergelincir di jalur curam.'),
('Kupluk, Buff, dan Sarung Tangan', 'Pakaian Luar', '0.3 kg', 'Wajib', 'semua', '/images/alat-kupluk-sarung-tangan.jpg', 'Kupluk menahan panas tubuh yang paling banyak lepas lewat kepala, buff melindungi leher dan saluran napas dari udara dingin serta debu, sedangkan sarung tangan menjaga jari tetap berfungsi saat suhu turun.', 'Kepala dan tangan adalah bagian tubuh yang paling cepat kehilangan panas. Jari yang kaku kedinginan menyulitkan pendaki membuka tas, memasang tenda, atau berpegangan pada akar dan tali di jalur curam.'),
('Kompas dan Peta Jalur', 'Navigasi & Darurat', '0.2 kg', 'Penting', 'semua', '/images/alat-kompas-peta.jpg', 'Kompas dan peta jalur cetak berfungsi sebagai penunjuk arah yang tidak bergantung pada baterai maupun sinyal. Keduanya dipakai memastikan posisi saat kabut turun atau ketika menemukan percabangan jalur yang tidak bertanda.', 'Ponsel kehabisan baterai dan sinyal hilang adalah hal biasa di gunung. Tersesat karena salah memilih percabangan saat kabut tebal merupakan penyebab umum pendaki hilang, dan mencari jalan kembali tanpa alat navigasi memakan waktu serta tenaga yang mungkin sudah menipis.');
